#!/bin/zsh
# 让 Codex 出豆仓的整套界面设计图：先有设计稿，再照着做。每个页面一张。
cd "$(dirname "$0")"
gen() {
  local name=$1; local prompt=$2
  [ -f "$name.png" ] && return
  local t0=$(date +%s)
  codex exec --skip-git-repo-check --ephemeral -c 'model_reasoning_effort="low"' -C "$PWD" -s workspace-write \
    "当前目录有两张参考图 ref_mascot.png 和 ref_mascot2.png，是产品的吉祥物「小豆」：一只珍珠白的圆滚滚小仓鼠，脖子上挂白色耳机，耳机外圈有琥珀色灯环。请先看这两张图，然后使用内置的 image_gen 工具（把参考图一起传入，保持小豆长相一致）生成一张 16:10 横向的高保真 UI 设计稿（像设计师在 Figma 里做的最终稿截图，正视图、不要透视、不要设备外壳以外的场景）：$prompt 生成后把最终图片复制到当前目录，命名为 $name.png，然后只回复文件名。" < /dev/null > "$name.log" 2>&1
  echo "$name $(( $(date +%s) - t0 ))s $([ -f $name.png ] && echo ok || echo FAIL)"
}
S="产品是一款 macOS 桌面应用「豆仓」：连接一颗 AI 录音豆（也能直接用 Mac 录音），把录音自动转成文字、整理成纪要和待办，并且可以向所有录音提问。设计语言：苹果 macOS 最新风格加乔纳森·艾维式的克制——大量留白但没有空洞、清晰的字号层级、对齐严谨、圆角统一、细腻的阴影和材质；界面像一台精密的录音棚仪器，有一点未来感。配色严格限定：暖白纸色背景（#F6F3EC）、石墨黑文字（#1A1A1A）、唯一强调色琥珀橙（#F2A33A），红色（#F0453A）只用于录音按钮；绝对不要蓝色、紫色、青色、渐变彩虹。界面文字全部是简体中文，字体像苹方，文字清晰可读、没有乱码。窗口是一个带红黄绿三个圆点的 macOS 窗口，左侧是窄侧栏：顶部是豆仓的小图标和名字，导航只有三项「总览」「录音」「知识库」，侧栏底部是一张小卡片显示「soundcore Work · 已连接 · 100%」。整体要让人眼前一亮，像一款获苹果设计奖的应用，而不是后台管理系统。"
gen ui_home "【总览页】右侧主区域：左上是小豆（中等大小，站在一个浅色圆台上）和一句大号问候「晚上好」，下面一行小字「有 3 件事等你处理」。旁边是一个醒目的红色胶囊按钮「开始录音」，紧挨着一个次要的下拉「声音来自：录音豆」。下方分两栏：左栏「接下来要做的」是 4 条带圆形勾选框的待办，每条下面小字写来自哪条录音；右栏「最近的录音」是 4 张横向卡片，每张有琥珀色场景小图标、标题、一行摘要、时长。页面底部一条很细的统计「本周 12 条 · 3 小时 20 分」。不要大数字统计块，不要图表。$S" &
gen ui_list "【录音页】右侧主区域分两列。中间一列是录音列表：顶部搜索框「搜标题、内容、话题」，下面一排筛选「全部 / 星标 / 有待办 / 有重点」，列表按「今天」「昨天」分组，每行有琥珀色场景小图标、粗体标题、一行灰色摘要、小字「23:21 · 0:25 · 灵感」，第一行是选中状态（浅琥珀底）。右边一列是这条录音的详情：大标题、小字日期时长、三个页签「纪要 / 文字稿 / 改写」，下面是「摘要」卡片和「要点」卡片（带琥珀色小圆点的列表）、「待办」卡片（带勾选框）。详情底部悬浮一条胶囊形播放条：琥珀色播放键、前后 15 秒、带琥珀色重点标记的波形、时间、「1.25×」。工具栏右上角有红色「录音」按钮。$S" &
gen ui_knowledge "【知识库页】右侧主区域居中的内容：顶部大标题「问问你的录音」，下面一个很大的圆角输入框，左侧琥珀色星光图标，占位文字「比如：上周和王总谈的价格是多少」，右侧圆形琥珀色发送按钮。输入框下面是一排浅琥珀色的建议问题胶囊：「最近这几天我都聊了什么？」「我还有哪些答应了别人的事？」「关于周会都说过什么？」。再下面是一张回答卡片：粗体问题、分三点的回答（每点后面有小的琥珀色出处编号）、底部「依据这几条录音」和三个小胶囊。最下面是「最近整理好的」三张录音摘要卡片。右上角工具栏有一个小搜索框「找原话」。$S" &
gen ui_stage "【录音进行中的全屏舞台】这一张是深色的：整个窗口内容区是石墨黑（#0E0E0F），没有侧栏。左上角小红点和「正在录音 · soundcore Work」，右上角一个小的「收起」按钮。画面中央偏上是小豆（戴着耳机在认真听，耳机灯环发琥珀光）和旁边超大的细体计时数字「12:48」。计时下方是一条横贯全宽的精致声波：很多细密的暖白色竖线，最右端几根是红色，声波上有两根琥珀色的重点标记竖线。声波下方居中是一行实时字幕「我们先把下周三的发布时间定下来。」。底部一排按钮：左边琥珀色「标重点 · 2」和「暂停」，右边「全部文字」和红色「结束」。背景右侧有一团很淡的暖红色光晕。$S" &
gen ui_device "【设备页】右侧主区域内容垂直水平都居中、不留大片空白：上半部分是一个大的展示区，中间是小豆坐在一个打开的白色充电仓里（像产品主视觉），旁边大字设备名「soundcore Work」和绿色小字「已连接」，下面一排三个圆形指标：「录音豆 100%」「充电盒 80%」「已用 6.5 MB / 58 GB」，每个是一个细的琥珀色圆环进度。再下面是两个按钮：红色「开始录音」和次要的「断开连接」。底部一行很小的灰字「固件 04.92 · 序列号 32000000A1B2C3D4 · 诊断日志」。$S" &
wait
